/**
 * CSV Reader & Analytics Web App
 * Handles CSV parsing, UI rendering, filtering, sorting, charts, and exports.
 */

// App State
let state = {
    rawFile: null,
    headers: [],
    data: [], // Array of row objects
    filteredData: [],
    hiddenColumns: new Set(),
    sortColumn: null,
    sortDirection: 'asc', // 'asc' or 'desc'
    currentPage: 1,
    pageSize: 25,
    chartInstance: null,
    radarChartInstance: null,
    currentPreset: null, // 'guild_damage', 'sample_sales', or null
    lastRawCsvText: '',
    isSingleViewMode: false
};

// DOM Elements
const uploadSection = document.getElementById('upload-section');
const dropZone = document.getElementById('drop-zone');
const csvFileInput = document.getElementById('csv-file-input');
const selectEncoding = document.getElementById('select-encoding');
const selectDelimiter = document.getElementById('select-delimiter');
const btnReparse = document.getElementById('btn-reparse');
const btnSampleData = document.getElementById('btn-sample-data');
const btnGuildData = document.getElementById('btn-guild-data');
const btnShareLink = document.getElementById('btn-share-link');
const btnShareCharLink = document.getElementById('btn-share-char-link');
const btnReset = document.getElementById('btn-reset');

const singleViewBanner = document.getElementById('single-view-banner');
const singleViewCharTitle = document.getElementById('single-view-char-title');
const btnUnlockFullView = document.getElementById('btn-unlock-full-view');

const workspaceSection = document.getElementById('workspace-section');
const benchmarkSelectBar = document.getElementById('benchmark-select-bar');
const benchmarkClassSelect = document.getElementById('benchmark-class-select');
const benchmarkCharSelect = document.getElementById('benchmark-char-select');

// Initialization & Event Listeners
document.addEventListener('DOMContentLoaded', () => {
    initEvents();
    checkUrlParametersOnLoad();
});

function initEvents() {
    // File input change
    if (csvFileInput) {
        csvFileInput.addEventListener('change', (e) => {
            if (e.target.files.length > 0) {
                handleFileSelect(e.target.files[0]);
            }
        });
    }

    // Drag and Drop
    if (dropZone) {
        dropZone.addEventListener('click', () => {
            if (csvFileInput) csvFileInput.click();
        });
        dropZone.addEventListener('dragover', (e) => {
            e.preventDefault();
            dropZone.classList.add('drag-over');
        });
        dropZone.addEventListener('dragleave', () => dropZone.classList.remove('drag-over'));
        dropZone.addEventListener('drop', (e) => {
            e.preventDefault();
            dropZone.classList.remove('drag-over');
            if (e.dataTransfer.files.length > 0) {
                handleFileSelect(e.dataTransfer.files[0]);
            }
        });
    }

    // Settings & Controls
    if (btnReparse) {
        btnReparse.addEventListener('click', () => {
            if (state.rawFile) {
                parseFile(state.rawFile);
            } else {
                Swal.fire({
                    icon: 'info',
                    title: 'ยังไม่ได้เลือกไฟล์',
                    text: 'กรุณาเลือกหรือลากวางไฟล์ CSV ก่อนครับ',
                    confirmColor: '#0284c7'
                });
            }
        });
    }

    if (btnSampleData) {
        btnSampleData.addEventListener('click', loadSampleData);
    }
    if (btnGuildData) {
        btnGuildData.addEventListener('click', loadGuildData);
    }

    if (btnReset) {
        btnReset.addEventListener('click', () => {
            state.rawFile = null;
            state.data = [];
            state.filteredData = [];
            state.headers = [];
            if (csvFileInput) csvFileInput.value = '';
            if (workspaceSection) workspaceSection.classList.add('hidden');
            if (singleViewBanner) singleViewBanner.classList.add('hidden');
            btnReset.classList.add('hidden');
        });
    }

    if (btnUnlockFullView) {
        btnUnlockFullView.addEventListener('click', () => {
            state.isSingleViewMode = false;
            if (singleViewBanner) singleViewBanner.classList.add('hidden');
            if (uploadSection) uploadSection.classList.remove('hidden');
            if (benchmarkSelectBar) benchmarkSelectBar.classList.remove('hidden');
            Swal.fire({
                icon: 'info',
                title: 'แสดงเมนูเลือกตัวละครทั้งหมดแล้ว',
                timer: 1500,
                showConfirmButton: false
            });
        });
    }

    // Benchmark Controls
    if (benchmarkClassSelect) {
        benchmarkClassSelect.addEventListener('change', () => {
            updateBenchmarkCharDropdown();
            renderCharacterBenchmark();
        });
    }
    if (benchmarkCharSelect) {
        benchmarkCharSelect.addEventListener('change', renderCharacterBenchmark);
    }

    // Share Link Controls
    if (btnShareLink) {
        btnShareLink.addEventListener('click', () => copyShareableLink());
    }
    if (btnShareCharLink) {
        btnShareCharLink.addEventListener('click', () => copyShareableLink());
    }
}

// File Selection Handler
function handleFileSelect(file) {
    if (!file.name.endsWith('.csv') && file.type !== 'text/csv' && file.type !== 'application/vnd.ms-excel') {
        Swal.fire({
            icon: 'error',
            title: 'รูปแบบไฟล์ไม่ถูกต้อง',
            text: 'กรุณาเลือกไฟล์ที่มีนามสกุล .csv เท่านั้น',
            confirmColor: '#0284c7'
        });
        return;
    }

    state.rawFile = file;
    parseFile(file);
}

// Parse CSV with PapaParse
function parseFile(fileOrString) {
    const encoding = selectEncoding.value;
    const delimiter = selectDelimiter.value;

    Swal.fire({
        title: 'กำลังอ่านไฟล์...',
        text: 'โปรดรอสักครู่',
        allowOutsideClick: false,
        didOpen: () => Swal.showLoading()
    });

    if (typeof fileOrString === 'string') {
        // Direct string parse (for sample data)
        parseCSVText(fileOrString, delimiter);
    } else {
        // FileReader for file objects with selected encoding
        const reader = new FileReader();
        reader.onload = function(e) {
            const csvContent = e.target.result;
            parseCSVText(csvContent, delimiter);
        };
        reader.onerror = function() {
            Swal.fire({
                icon: 'error',
                title: 'เกิดข้อผิดพลาดในการอ่านไฟล์',
                text: 'ไม่สามารถอ่านไฟล์ตาม Encoding ที่เลือกได้',
                confirmColor: '#0284c7'
            });
        };
        reader.readAsText(fileOrString, encoding);
    }
}

function parseCSVText(csvText, delimiter, autoSelectChar = null) {
    state.lastRawCsvText = csvText;

    // Smart detection: Skip title metadata lines from Google Sheets / Excel exports
    let cleanedText = csvText;
    const lines = csvText.split(/\r?\n/);
    if (lines.length > 2) {
        let maxColIndex = 0;
        let maxCols = 0;
        for (let i = 0; i < Math.min(lines.length, 10); i++) {
            const cols = lines[i].split(',').filter(c => c.trim() !== '').length;
            if (cols > maxCols) {
                maxCols = cols;
                maxColIndex = i;
            }
        }
        if (maxColIndex > 0) {
            cleanedText = lines.slice(maxColIndex).join('\n');
        }
    }

    Papa.parse(cleanedText, {
        header: true,
        skipEmptyLines: true,
        delimiter: delimiter || "",
        dynamicTyping: true,
        complete: function(results) {
            Swal.close();
            if (results.errors && results.errors.length > 0) {
                console.warn('CSV Parse Warnings/Errors:', results.errors);
            }

            state.headers = results.meta.fields || [];
            state.data = results.data || [];
            state.filteredData = [...state.data];

            // Show workspace section
            if (workspaceSection) workspaceSection.classList.remove('hidden');
            if (btnReset) btnReset.classList.remove('hidden');

            populateBenchmarkSelectors();

            const charCol = getCharColumn();

            if (autoSelectChar && benchmarkCharSelect) {
                const matchingRow = state.data.find(r => String(r[charCol]).toLowerCase().trim() === autoSelectChar.toLowerCase().trim());
                if (matchingRow) {
                    benchmarkCharSelect.value = matchingRow[charCol];
                } else {
                    benchmarkCharSelect.value = '';
                }
            } else if (benchmarkCharSelect) {
                benchmarkCharSelect.value = '';
            }

            renderCharacterBenchmark();
        }
    });
}

// Update KPI Stats
function updateKPIs() {
    kpiRows.textContent = state.data.length.toLocaleString();
    kpiCols.textContent = state.headers.length.toLocaleString();

    // Calculate total null/empty cells
    let nullCount = 0;
    state.data.forEach(row => {
        state.headers.forEach(h => {
            if (row[h] === null || row[h] === undefined || row[h] === '') {
                nullCount++;
            }
        });
    });
    kpiNulls.textContent = nullCount.toLocaleString();
}

// Column Visibility Toggle Menu
function renderColumnToggleMenu() {
    colToggleMenu.innerHTML = '';
    state.headers.forEach(header => {
        const item = document.createElement('label');
        item.className = 'flex items-center space-x-2 text-xs text-slate-700 hover:bg-slate-50 p-1.5 rounded cursor-pointer';
        
        const checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.checked = !state.hiddenColumns.has(header);
        checkbox.className = 'rounded text-brand-600 focus:ring-brand-500';
        checkbox.addEventListener('change', () => {
            if (checkbox.checked) {
                state.hiddenColumns.delete(header);
            } else {
                state.hiddenColumns.add(header);
            }
            renderTable();
        });

        const span = document.createElement('span');
        span.textContent = header;
        span.className = 'truncate';

        item.appendChild(checkbox);
        item.appendChild(span);
        colToggleMenu.appendChild(item);
    });
}

// Apply Search & Filter
function applySearchAndFilter() {
    const searchTerm = tableSearch.value.trim().toLowerCase();

    if (!searchTerm) {
        state.filteredData = [...state.data];
    } else {
        state.filteredData = state.data.filter(row => {
            return state.headers.some(h => {
                const val = row[h];
                return val !== null && val !== undefined && String(val).toLowerCase().includes(searchTerm);
            });
        });
    }

    if (state.sortColumn) {
        sortData(state.sortColumn, state.sortDirection, false);
    } else {
        renderTable();
    }
}

// Sort Data
function sortData(column, direction, toggleDir = true) {
    if (toggleDir) {
        if (state.sortColumn === column) {
            state.sortDirection = state.sortDirection === 'asc' ? 'desc' : 'asc';
        } else {
            state.sortColumn = column;
            state.sortDirection = 'asc';
        }
    }

    const dirMultiplier = state.sortDirection === 'asc' ? 1 : -1;

    state.filteredData.sort((a, b) => {
        const valA = a[column];
        const valB = b[column];

        if (valA === null || valA === undefined) return 1;
        if (valB === null || valB === undefined) return -1;

        if (typeof valA === 'number' && typeof valB === 'number') {
            return (valA - valB) * dirMultiplier;
        }

        return String(valA).localeCompare(String(valB), 'th', { numeric: true }) * dirMultiplier;
    });

    renderTable();
}

// Render Data Table
function renderTable() {
    // 1. Render Table Header
    tableHead.innerHTML = '';
    const trHead = document.createElement('tr');
    
    state.headers.forEach(header => {
        if (state.hiddenColumns.has(header)) return;

        const th = document.createElement('th');
        th.className = 'px-4 py-3 border-b border-slate-200 font-semibold sortable';
        
        let sortIcon = '<i class="fa-solid fa-sort text-slate-300 ml-1"></i>';
        if (state.sortColumn === header) {
            sortIcon = state.sortDirection === 'asc' 
                ? '<i class="fa-solid fa-sort-up text-brand-600 ml-1"></i>' 
                : '<i class="fa-solid fa-sort-down text-brand-600 ml-1"></i>';
        }

        th.innerHTML = `<div class="flex items-center justify-between">
            <span class="truncate">${header}</span>
            ${sortIcon}
        </div>`;

        th.addEventListener('click', () => sortData(header));
        trHead.appendChild(th);
    });
    tableHead.appendChild(trHead);

    // 2. Paginate Data
    const totalRows = state.filteredData.length;
    const pageSize = state.pageSize;
    const totalPages = Math.ceil(totalRows / pageSize) || 1;
    if (state.currentPage > totalPages) state.currentPage = totalPages;

    const startIdx = (state.currentPage - 1) * pageSize;
    const endIdx = Math.min(startIdx + pageSize, totalRows);
    const pageData = state.filteredData.slice(startIdx, endIdx);

    // 3. Render Table Body
    tableBody.innerHTML = '';

    if (pageData.length === 0) {
        const trEmpty = document.createElement('tr');
        const visibleColCount = state.headers.length - state.hiddenColumns.size;
        trEmpty.innerHTML = `<td colspan="${visibleColCount}" class="px-4 py-8 text-center text-slate-400">
            <i class="fa-solid fa-folder-open text-2xl mb-2 block"></i>
            ไม่พบข้อมูลที่ตรงกับคำค้นหา
        </td>`;
        tableBody.appendChild(trEmpty);
    } else {
        pageData.forEach((row, idx) => {
            const tr = document.createElement('tr');
            tr.className = idx % 2 === 0 ? 'bg-white hover:bg-slate-50' : 'bg-slate-50/50 hover:bg-slate-100/60';

            state.headers.forEach(header => {
                if (state.hiddenColumns.has(header)) return;

                const td = document.createElement('td');
                td.className = 'px-4 py-2.5 whitespace-nowrap text-xs text-slate-700';
                
                const val = row[header];
                if (val === null || val === undefined || val === '') {
                    td.innerHTML = '<span class="text-slate-300 italic">-</span>';
                } else {
                    td.textContent = val;
                }
                tr.appendChild(td);
            });
            tableBody.appendChild(tr);
        });
    }

    // 4. Update Pagination Info & Controls
    paginationInfo.textContent = `แสดง ${totalRows === 0 ? 0 : startIdx + 1} ถึง ${endIdx} จากทั้งหมด ${totalRows.toLocaleString()} แถว`;

    renderPaginationControls(totalPages);
}

function renderPaginationControls(totalPages) {
    paginationControls.innerHTML = '';

    if (totalPages <= 1) return;

    // Previous Button
    const btnPrev = document.createElement('button');
    btnPrev.className = `px-2.5 py-1 rounded border text-xs font-medium ${state.currentPage === 1 ? 'text-slate-300 border-slate-200 cursor-not-allowed' : 'text-slate-600 border-slate-300 hover:bg-slate-100'}`;
    btnPrev.innerHTML = '<i class="fa-solid fa-chevron-left"></i>';
    btnPrev.disabled = state.currentPage === 1;
    btnPrev.addEventListener('click', () => {
        if (state.currentPage > 1) {
            state.currentPage--;
            renderTable();
        }
    });
    paginationControls.appendChild(btnPrev);

    // Page Numbers (Show window of pages)
    let startPage = Math.max(1, state.currentPage - 2);
    let endPage = Math.min(totalPages, startPage + 4);
    if (endPage - startPage < 4) {
        startPage = Math.max(1, endPage - 4);
    }

    for (let p = startPage; p <= endPage; p++) {
        const btnPage = document.createElement('button');
        btnPage.className = `px-3 py-1 rounded text-xs font-medium ${p === state.currentPage ? 'bg-brand-600 text-white font-semibold' : 'text-slate-600 border border-slate-300 hover:bg-slate-100'}`;
        btnPage.textContent = p;
        btnPage.addEventListener('click', () => {
            state.currentPage = p;
            renderTable();
        });
        paginationControls.appendChild(btnPage);
    }

    // Next Button
    const btnNext = document.createElement('button');
    btnNext.className = `px-2.5 py-1 rounded border text-xs font-medium ${state.currentPage === totalPages ? 'text-slate-300 border-slate-200 cursor-not-allowed' : 'text-slate-600 border-slate-300 hover:bg-slate-100'}`;
    btnNext.innerHTML = '<i class="fa-solid fa-chevron-right"></i>';
    btnNext.disabled = state.currentPage === totalPages;
    btnNext.addEventListener('click', () => {
        if (state.currentPage < totalPages) {
            state.currentPage++;
            renderTable();
        }
    });
    paginationControls.appendChild(btnNext);
}

// Analytics & Chart Builder
function populateChartDropdowns() {
    chartXAxisSelect.innerHTML = '';
    chartYAxisSelect.innerHTML = '';

    state.headers.forEach(header => {
        const optX = document.createElement('option');
        optX.value = header;
        optX.textContent = header;
        chartXAxisSelect.appendChild(optX);

        const optY = document.createElement('option');
        optY.value = header;
        optY.textContent = header;
        chartYAxisSelect.appendChild(optY);
    });

    // Smart default: Select 1st column for X, 2nd column (or numerical) for Y
    if (state.headers.length > 0) {
        chartXAxisSelect.selectedIndex = 0;
        const numColIdx = state.headers.findIndex(h => typeof state.data[0]?.[h] === 'number');
        if (numColIdx !== -1) {
            chartYAxisSelect.selectedIndex = numColIdx;
        } else if (state.headers.length > 1) {
            chartYAxisSelect.selectedIndex = 1;
        }
    }
}

function updateChart() {
    const chartType = chartTypeSelect.value;
    const xAxisCol = chartXAxisSelect.value;
    const yAxisCol = chartYAxisSelect.value;
    const aggType = chartAggregateSelect.value;

    if (!xAxisCol || !yAxisCol) return;

    // Aggregate Data
    const aggMap = new Map();

    state.filteredData.forEach(row => {
        const key = row[xAxisCol] !== null && row[xAxisCol] !== undefined ? String(row[xAxisCol]) : '(ไม่มีข้อมูล)';
        const val = parseFloat(row[yAxisCol]) || 0;

        if (!aggMap.has(key)) {
            aggMap.set(key, { sum: 0, count: 0 });
        }
        const curr = aggMap.get(key);
        curr.sum += val;
        curr.count += 1;
    });

    const labels = Array.from(aggMap.keys());
    const dataValues = labels.map(key => {
        const stat = aggMap.get(key);
        if (aggType === 'sum') return stat.sum;
        if (aggType === 'avg') return stat.count > 0 ? (stat.sum / stat.count) : 0;
        if (aggType === 'count') return stat.count;
    });

    // Destroy previous chart instance
    if (state.chartInstance) {
        state.chartInstance.destroy();
    }

    const ctx = document.getElementById('analytics-chart-canvas').getContext('2d');
    
    // Custom colors palette
    const colors = [
        '#0284c7', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6',
        '#ec4899', '#06b6d4', '#84cc16', '#6366f1', '#14b8a6'
    ];

    state.chartInstance = new Chart(ctx, {
        type: chartType,
        data: {
            labels: labels,
            datasets: [{
                label: `${aggType.toUpperCase()} of ${yAxisCol}`,
                data: dataValues,
                backgroundColor: chartType === 'pie' || chartType === 'doughnut' ? colors : 'rgba(2, 132, 199, 0.7)',
                borderColor: chartType === 'pie' || chartType === 'doughnut' ? '#ffffff' : '#0284c7',
                borderWidth: 1.5,
                borderRadius: chartType === 'bar' ? 6 : 0
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
                legend: {
                    display: chartType === 'pie' || chartType === 'doughnut',
                    position: 'bottom'
                },
                title: {
                    display: true,
                    text: `แสดงกราฟ ${chartType.toUpperCase()} : ${xAxisCol} vs ${yAxisCol} (${aggType})`,
                    font: { family: 'Sarabun', size: 14, weight: 'bold' }
                }
            },
            scales: (chartType === 'bar' || chartType === 'line') ? {
                y: { beginAtZero: true, grid: { color: '#f1f5f9' } },
                x: { grid: { display: false } }
            } : {}
        }
    });
}

// Numeric Parser Helper
function parseNumericValue(val) {
    if (val === null || val === undefined || val === '') return null;
    if (typeof val === 'number') return isNaN(val) ? null : val;
    const str = String(val).replace(/%/g, '').replace(/,/g, '').trim();
    const parsed = parseFloat(str);
    return isNaN(parsed) ? null : parsed;
}

// Column Finder Helpers
function getCharColumn() {
    return state.headers.find(h => h.includes('ตัวละคร') || h.toLowerCase().includes('name') || h.toLowerCase().includes('character')) || state.headers[0];
}

function getClassColumn() {
    return state.headers.find(h => h.includes('อาชีพ') || h.toLowerCase().includes('class') || h.toLowerCase().includes('job')) || state.headers[1];
}

// Populate Benchmark Selectors
function populateBenchmarkSelectors() {
    if (!benchmarkClassSelect || !benchmarkCharSelect) return;

    const classCol = getClassColumn();
    
    // Extract unique classes
    const classes = new Set();
    state.data.forEach(r => {
        if (r[classCol]) classes.add(String(r[classCol]).trim());
    });

    benchmarkClassSelect.innerHTML = '<option value="">-- แสดงทุกอาชีพ --</option>';
    Array.from(classes).sort().forEach(c => {
        const opt = document.createElement('option');
        opt.value = c;
        opt.textContent = c;
        benchmarkClassSelect.appendChild(opt);
    });

    updateBenchmarkCharDropdown();
}

function updateBenchmarkCharDropdown(keepSelection = true) {
    if (!benchmarkCharSelect) return;

    const selectedClass = benchmarkClassSelect ? benchmarkClassSelect.value.trim() : '';
    const classCol = getClassColumn();
    const charCol = getCharColumn();

    const previousChar = benchmarkCharSelect.value ? benchmarkCharSelect.value.trim() : '';

    benchmarkCharSelect.innerHTML = '';

    const filteredChars = state.data.filter(r => {
        if (!selectedClass) return true;
        const rClass = r[classCol] ? String(r[classCol]).trim() : '';
        return rClass.toLowerCase() === selectedClass.toLowerCase();
    });

    if (!selectedClass || filteredChars.length === 0) {
        const defaultOpt = document.createElement('option');
        defaultOpt.value = '';
        defaultOpt.textContent = '-- เลือกชื่อตัวละครเพื่อเปรียบเทียบ --';
        benchmarkCharSelect.appendChild(defaultOpt);
    }

    filteredChars.forEach(r => {
        const name = r[charCol] ? String(r[charCol]).trim() : '';
        const job = r[classCol] ? String(r[classCol]).trim() : '';
        if (name) {
            const opt = document.createElement('option');
            opt.value = name;
            opt.textContent = `${name} (${job})`;
            benchmarkCharSelect.appendChild(opt);
        }
    });

    const isPrevInList = previousChar && filteredChars.some(r => r[charCol] && String(r[charCol]).trim() === previousChar);

    if (keepSelection && isPrevInList) {
        benchmarkCharSelect.value = previousChar;
    } else if (selectedClass && filteredChars.length > 0) {
        const firstCharName = filteredChars[0][charCol] ? String(filteredChars[0][charCol]).trim() : '';
        benchmarkCharSelect.value = firstCharName;
    } else {
        benchmarkCharSelect.value = '';
    }
}

function renderCharacterBenchmark() {
    const emptyState = document.getElementById('benchmark-empty-state');
    const headerCard = document.getElementById('benchmark-header-card');
    const detailsContainer = document.getElementById('benchmark-details-container');
    const cardsGrid = document.getElementById('benchmark-cards-grid');

    if (!benchmarkCharSelect || !benchmarkCharSelect.value) {
        if (emptyState) emptyState.classList.remove('hidden');
        if (headerCard) headerCard.classList.add('hidden');
        if (detailsContainer) detailsContainer.classList.add('hidden');
        return;
    }

    const selectedCharName = benchmarkCharSelect.value.trim();
    const charCol = getCharColumn();
    const classCol = getClassColumn();

    const charRow = state.data.find(r => r[charCol] && String(r[charCol]).trim().toLowerCase() === selectedCharName.toLowerCase());
    if (!charRow) return;

    const charClass = String(charRow[classCol] || 'Unknown').trim();
    
    // Get all peers in the same class
    const classPeers = state.data.filter(r => r[classCol] && String(r[classCol]).trim().toLowerCase() === charClass.toLowerCase());

    // Identify numerical columns (excluding character name & class)
    const numericalCols = state.headers.filter(h => {
        if (h === charCol || h === classCol) return false;
        const vals = state.data.map(r => parseNumericValue(r[h])).filter(v => v !== null);
        return vals.length > 0 && (vals.length / state.data.length) >= 0.5;
    });

    // Populate Header Card
    document.getElementById('bench-char-name').textContent = charRow[charCol];
    document.getElementById('bench-char-class').textContent = charClass;

    cardsGrid.innerHTML = '';
    let aboveCount = 0;
    let belowCount = 0;

    numericalCols.forEach(col => {
        const peerValues = classPeers.map(r => parseNumericValue(r[col])).filter(v => v !== null);
        if (peerValues.length === 0) return;

        const min = Math.min(...peerValues);
        const max = Math.max(...peerValues);
        const sum = peerValues.reduce((a, b) => a + b, 0);
        const avg = sum / peerValues.length;

        const charVal = parseNumericValue(charRow[col]);
        if (charVal === null) return;

        const diff = charVal - avg;
        const diffPct = avg !== 0 ? ((diff / Math.abs(avg)) * 100) : 0;

        if (diff >= 0) aboveCount++;
        else belowCount++;

        // Calculate visual progress with Average (Avg) fixed at 50% center
        let charPosPct = 50;
        if (charVal >= avg) {
            const diffMax = max - avg;
            charPosPct = 50 + (diffMax > 0 ? Math.min(50, ((charVal - avg) / diffMax) * 50) : 0);
        } else {
            const diffMin = avg - min;
            charPosPct = 50 - (diffMin > 0 ? Math.min(50, ((avg - charVal) / diffMin) * 50) : 0);
        }
        charPosPct = Math.max(0, Math.min(100, charPosPct));

        // Diff Badge styling
        let diffBadgeClass = 'bg-slate-100 text-slate-700 border-slate-200';
        let diffIcon = '<i class="fa-solid fa-minus text-xs"></i>';
        let diffText = 'เท่ากับค่าเฉลี่ย';

        if (diff > 0) {
            diffBadgeClass = 'bg-emerald-50 text-emerald-700 border-emerald-200 font-semibold';
            diffIcon = '<i class="fa-solid fa-arrow-up text-xs"></i>';
            diffText = `+${diff.toLocaleString(undefined, { maximumFractionDigits: 1 })} (+${diffPct.toFixed(1)}%)`;
        } else if (diff < 0) {
            diffBadgeClass = 'bg-rose-50 text-rose-700 border-rose-200 font-semibold';
            diffIcon = '<i class="fa-solid fa-arrow-down text-xs"></i>';
            diffText = `${diff.toLocaleString(undefined, { maximumFractionDigits: 1 })} (${diffPct.toFixed(1)}%)`;
        }

        const card = document.createElement('div');
        card.className = 'bg-white p-5 rounded-2xl border border-slate-200/80 shadow-xs flex flex-col justify-between space-y-4 hover:border-purple-300 hover:shadow-md transition-all';
        card.innerHTML = `
            <div class="flex items-start justify-between gap-3">
                <div>
                    <span class="text-xs font-bold text-slate-500 uppercase tracking-wide">${col}</span>
                    <div class="text-2xl font-extrabold text-slate-900 mt-1">${charVal.toLocaleString(undefined, { maximumFractionDigits: 2 })}</div>
                </div>
                <div class="px-2.5 py-1.5 rounded-full text-xs border ${diffBadgeClass} flex items-center gap-1 shadow-2xs shrink-0">
                    ${diffIcon}
                    <span>${diffText}</span>
                </div>
            </div>

            <div class="space-y-2 pt-2 border-t border-slate-100">
                <div class="flex items-center justify-between text-[11px] text-slate-500 font-medium">
                    <span>Min: <b class="text-slate-700">${min.toLocaleString(undefined, { maximumFractionDigits: 1 })}</b></span>
                    <span class="text-purple-700 font-bold">Avg: ${avg.toLocaleString(undefined, { maximumFractionDigits: 1 })}</span>
                    <span>Max: <b class="text-slate-700">${max.toLocaleString(undefined, { maximumFractionDigits: 1 })}</b></span>
                </div>

                <div class="w-full bg-slate-100 rounded-full h-2.5 relative overflow-hidden">
                    <div class="h-full bg-gradient-to-r ${diff >= 0 ? 'from-purple-500 to-indigo-500' : 'from-purple-500 to-amber-500'} rounded-full transition-all duration-500" style="width: ${charPosPct}%"></div>
                    <div class="absolute top-0 bottom-0 w-1 bg-slate-900 shadow-xs z-10 -translate-x-1/2" style="left: 50%" title="ค่าเฉลี่ย (Avg): ${avg.toLocaleString(undefined, { maximumFractionDigits: 1 })}"></div>
                </div>
            </div>
        `;
        cardsGrid.appendChild(card);
    });

    const elemAbove = document.getElementById('bench-above-avg-count');
    const elemBelow = document.getElementById('bench-below-avg-count');
    if (elemAbove) elemAbove.textContent = aboveCount;
    if (elemBelow) elemBelow.textContent = belowCount;

    if (emptyState) emptyState.classList.add('hidden');
    if (headerCard) headerCard.classList.remove('hidden');
    if (detailsContainer) detailsContainer.classList.remove('hidden');
}

// Summary Statistics for Numerical Columns (Per Class)
function renderStatsSummary() {
    statsSummaryTbody.innerHTML = '';

    const selectedClass = statsClassFilter ? statsClassFilter.value : 'ALL';
    const classCol = state.headers.find(h => h.includes('อาชีพ') || h.toLowerCase().includes('class') || h.toLowerCase().includes('job')) || state.headers[1];

    let dataset = state.data;
    if (selectedClass && selectedClass !== 'ALL') {
        dataset = state.data.filter(r => String(r[classCol] || '').trim() === selectedClass);
    }

    const numericCols = state.headers.filter(h => {
        const validValues = dataset.map(r => parseNumericValue(r[h])).filter(v => v !== null);
        return validValues.length > 0 && (validValues.length / dataset.length) >= 0.5;
    });

    if (numericCols.length === 0) {
        statsSummaryTbody.innerHTML = `<tr><td colspan="6" class="px-4 py-6 text-center text-slate-400">ไม่พบคอลัมน์ที่เป็นตัวเลข</td></tr>`;
        return;
    }

    numericCols.forEach(col => {
        const values = dataset.map(r => parseNumericValue(r[col])).filter(v => v !== null);
        const count = values.length;
        const sum = values.reduce((a, b) => a + b, 0);
        const min = count > 0 ? Math.min(...values) : 0;
        const max = count > 0 ? Math.max(...values) : 0;
        const mean = count > 0 ? (sum / count) : 0;

        const tr = document.createElement('tr');
        tr.className = 'hover:bg-slate-50';
        tr.innerHTML = `
            <td class="px-4 py-3 font-semibold text-slate-800">${col}</td>
            <td class="px-4 py-3 text-slate-600 font-medium">${count.toLocaleString()} แถว</td>
            <td class="px-4 py-3 text-amber-600 font-medium">${min.toLocaleString(undefined, { maximumFractionDigits: 2 })}</td>
            <td class="px-4 py-3 text-emerald-600 font-medium">${max.toLocaleString(undefined, { maximumFractionDigits: 2 })}</td>
            <td class="px-4 py-3 text-brand-600 font-bold">${mean.toLocaleString(undefined, { maximumFractionDigits: 2 })}</td>
            <td class="px-4 py-3 text-purple-700 font-medium">${sum.toLocaleString(undefined, { maximumFractionDigits: 2 })}</td>
        `;
        statsSummaryTbody.appendChild(tr);
    });
}

// Export CSV & JSON
function exportCSV() {
    if (state.filteredData.length === 0) {
        Swal.fire({ icon: 'warning', title: 'ไม่มีข้อมูลที่จะส่งออก', confirmColor: '#0284c7' });
        return;
    }

    // Filter out hidden columns
    const exportHeaders = state.headers.filter(h => !state.hiddenColumns.has(h));
    const exportData = state.filteredData.map(row => {
        const obj = {};
        exportHeaders.forEach(h => obj[h] = row[h]);
        return obj;
    });

    const csvStr = Papa.unparse(exportData);
    const blob = new Blob(["\ufeff" + csvStr], { type: 'text/csv;charset=utf-8;' }); // BOM for Thai Excel compatibility
    const url = URL.createObjectURL(blob);

    const a = document.createElement('a');
    a.href = url;
    a.download = `exported_data_${new Date().toISOString().slice(0,10)}.csv`;
    a.click();
    URL.revokeObjectURL(url);
}

function exportJSON() {
    if (state.filteredData.length === 0) {
        Swal.fire({ icon: 'warning', title: 'ไม่มีข้อมูลที่จะส่งออก', confirmColor: '#0284c7' });
        return;
    }

    const exportHeaders = state.headers.filter(h => !state.hiddenColumns.has(h));
    const exportData = state.filteredData.map(row => {
        const obj = {};
        exportHeaders.forEach(h => obj[h] = row[h]);
        return obj;
    });

    const jsonStr = JSON.stringify(exportData, null, 2);
    const blob = new Blob([jsonStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);

    const a = document.createElement('a');
    a.href = url;
    a.download = `exported_data_${new Date().toISOString().slice(0,10)}.json`;
    a.click();
    URL.revokeObjectURL(url);
}

// Switch Tab Helper
function switchToTab(tabBtnId) {
    const btn = document.getElementById(tabBtnId);
    if (!btn) return;

    document.querySelectorAll('.tab-btn').forEach(b => {
        b.classList.remove('active', 'border-brand-600', 'text-brand-600');
        b.classList.add('border-transparent', 'text-slate-500');
    });
    btn.classList.add('active', 'border-brand-600', 'text-brand-600');

    document.querySelectorAll('.tab-content').forEach(c => c.classList.add('hidden'));

    if (tabBtnId === 'tab-btn-table') {
        document.getElementById('tab-content-table').classList.remove('hidden');
    } else if (tabBtnId === 'tab-btn-benchmark') {
        document.getElementById('tab-content-benchmark').classList.remove('hidden');
        renderCharacterBenchmark();
    } else if (tabBtnId === 'tab-btn-charts') {
        document.getElementById('tab-content-charts').classList.remove('hidden');
        updateChart();
    } else if (tabBtnId === 'tab-btn-stats') {
        document.getElementById('tab-content-stats').classList.remove('hidden');
        renderStatsSummary();
    }
}

// Load Pre-baked Sample Data
function loadSampleData(autoSelectChar = null) {
    fetch('sample_sales_thai.csv')
        .then(res => res.text())
        .then(text => {
            selectEncoding.value = 'UTF-8';
            selectDelimiter.value = '';
            state.currentPreset = 'sample_sales';
            parseCSVText(text, '', autoSelectChar);
        })
        .catch(err => {
            console.error(err);
            Swal.fire({
                icon: 'error',
                title: 'ไม่สามารถโหลดข้อมูลตัวอย่างได้',
                text: 'กรุณาตรวจสอบว่ามีไฟล์ sample_sales_thai.csv อยู่หรือไม่',
                confirmColor: '#0284c7'
            });
        });
}

// Load Guild Damage Data
function loadGuildData(autoSelectChar = null) {
    state.currentPreset = 'guild_damage';
    fetch('guild_damage.csv')
        .then(res => res.text())
        .then(text => {
            selectEncoding.value = 'UTF-8';
            selectDelimiter.value = '';
            parseCSVText(text, '', autoSelectChar);
        })
        .catch(err => {
            console.warn('Fetch failed (likely file:// protocol), using built-in preset fallback:', err);
            selectEncoding.value = 'UTF-8';
            selectDelimiter.value = '';
            parseCSVText(PRESET_GUILD_CSV, '', autoSelectChar);
        });
}

// Check URL parameters on page load
function checkUrlParametersOnLoad() {
    const urlParams = new URLSearchParams(window.location.search);
    const hash = window.location.hash;

    let fileParam = urlParams.get('file');
    const charParam = urlParams.get('char');
    const viewParam = urlParams.get('view');

    // Single view mode check (Hide upload section & dropdown bar on shared report page)
    if (viewParam === 'single' || (charParam && viewParam !== 'full')) {
        state.isSingleViewMode = true;

        if (uploadSection) uploadSection.classList.add('hidden');
        if (benchmarkSelectBar) benchmarkSelectBar.classList.add('hidden');
        if (btnShareCharLink) btnShareCharLink.classList.add('hidden');
        if (singleViewBanner) singleViewBanner.classList.remove('hidden');
        if (singleViewCharTitle && charParam) {
            singleViewCharTitle.textContent = `กำลังดูข้อมูลตัวละคร: ${charParam}`;
        }
    } else {
        state.isSingleViewMode = false;
        if (uploadSection) uploadSection.classList.remove('hidden');
        if (benchmarkSelectBar) benchmarkSelectBar.classList.remove('hidden');
        if (btnShareCharLink) btnShareCharLink.classList.remove('hidden');
        if (singleViewBanner) singleViewBanner.classList.add('hidden');
    }

    // 1. Check if compact class JSON data is in URL hash (#data=...)
    if (hash && hash.includes('data=')) {
        try {
            const compressedData = hash.split('data=')[1].split('&')[0];
            const decompressedJson = LZString.decompressFromEncodedURIComponent(compressedData);
            if (decompressedJson) {
                const parsed = JSON.parse(decompressedJson);
                if (parsed.h && parsed.r) {
                    state.headers = parsed.h;
                    state.data = parsed.r.map(rowVals => {
                        const obj = {};
                        parsed.h.forEach((h, idx) => {
                            obj[h] = rowVals[idx];
                        });
                        return obj;
                    });
                    state.filteredData = [...state.data];
                    state.currentPreset = null;

                    if (workspaceSection) workspaceSection.classList.remove('hidden');
                    populateBenchmarkSelectors();

                    const charCol = getCharColumn();
                    if (charParam && benchmarkCharSelect) {
                        const matchingRow = state.data.find(r => String(r[charCol]).toLowerCase().trim() === charParam.toLowerCase().trim());
                        if (matchingRow) {
                            benchmarkCharSelect.value = matchingRow[charCol];
                        }
                    }
                    renderCharacterBenchmark();
                    return;
                }
            }
        } catch (e) {
            console.error('Failed to decompress JSON data from URL hash:', e);
        }
    }

    // 2. Check if raw CSV data is in URL hash (#csv=...)
    if (hash && hash.includes('csv=')) {
        try {
            const compressedData = hash.split('csv=')[1].split('&')[0];
            const decompressedCsv = LZString.decompressFromEncodedURIComponent(compressedData);
            if (decompressedCsv) {
                state.currentPreset = null;
                parseCSVText(decompressedCsv, '', charParam);
                return;
            }
        } catch (e) {
            console.error('Failed to decompress CSV from URL hash:', e);
        }
    }

    // 3. Fallback to preset files if no CSV/data hash fragment is provided
    if (fileParam === 'guild_damage' || (!fileParam && !hash.includes('csv=') && !hash.includes('data='))) {
        loadGuildData(charParam);
        return;
    } else if (fileParam === 'sample') {
        loadSampleData(charParam);
        return;
    }
}

// Generate & Copy Ultra-Short Shareable URL (Compact Compression + TinyURL)
async function copyShareableLink(targetChar = null) {
    if (state.data.length === 0) {
        const Toast = Swal.mixin({
            toast: true,
            position: 'bottom',
            showConfirmButton: false,
            timer: 2500,
            timerProgressBar: true
        });
        Toast.fire({
            icon: 'warning',
            title: 'กรุณาอัปโหลดหรือเลือกไฟล์ CSV ก่อนครับ'
        });
        return;
    }

    const selectedChar = targetChar || (benchmarkCharSelect ? benchmarkCharSelect.value.trim() : '');
    const baseUrl = window.location.origin + window.location.pathname;

    const charCol = getCharColumn();
    const classCol = getClassColumn();
    
    const charRow = state.data.find(r => r[charCol] && String(r[charCol]).trim().toLowerCase() === selectedChar.toLowerCase());
    
    let longUrl = '';

    // 1. Pack only peers of this character's class into compact JSON format
    if (charRow) {
        const charClass = String(charRow[classCol] || '').trim();
        const classPeers = state.data.filter(r => r[classCol] && String(r[classCol]).trim().toLowerCase() === charClass.toLowerCase());
        
        const validHeaders = state.headers.filter(h => h && h.trim());
        const compactData = {
            h: validHeaders,
            r: classPeers.map(r => validHeaders.map(h => r[h] !== undefined ? r[h] : ''))
        };

        try {
            const jsonStr = JSON.stringify(compactData);
            const compressed = LZString.compressToEncodedURIComponent(jsonStr);
            longUrl = `${baseUrl}?char=${encodeURIComponent(selectedChar)}&view=single#data=${compressed}`;
        } catch (e) {
            console.error('Compact compression failed, fallback to raw csv:', e);
        }
    }

    // 2. Fallback to full CSV compression if class packing was skipped
    if (!longUrl && state.lastRawCsvText) {
        try {
            const compressed = LZString.compressToEncodedURIComponent(state.lastRawCsvText);
            longUrl = `${baseUrl}?char=${encodeURIComponent(selectedChar)}&view=single#csv=${compressed}`;
        } catch (err) {
            longUrl = `${baseUrl}?file=guild_damage${selectedChar ? '&char=' + encodeURIComponent(selectedChar) : ''}&view=single`;
        }
    }

    if (!longUrl) {
        longUrl = `${baseUrl}?file=guild_damage${selectedChar ? '&char=' + encodeURIComponent(selectedChar) : ''}&view=single`;
    }

    // 3. Shorten URL via TinyURL API for an ultra-short 20-character link (e.g. https://tinyurl.com/2y6fke3g)
    let finalShareUrl = longUrl;
    try {
        const tinyUrlApi = `https://tinyurl.com/api-create.php?url=${encodeURIComponent(longUrl)}`;
        const res = await fetch(tinyUrlApi);
        if (res.ok) {
            const shortText = await res.text();
            if (shortText && shortText.startsWith('http')) {
                finalShareUrl = shortText.trim();
            }
        }
    } catch (apiErr) {
        console.warn('TinyURL shortener offline or blocked, using compact URL:', apiErr);
    }

    // Copy to clipboard automatically and show bottom toast alert
    navigator.clipboard.writeText(finalShareUrl).then(() => {
        const Toast = Swal.mixin({
            toast: true,
            position: 'bottom',
            showConfirmButton: false,
            timer: 3000,
            timerProgressBar: true
        });
        Toast.fire({
            icon: 'success',
            title: `คัดลอกลิงก์สั้นแชร์ตัวละคร (${selectedChar || 'ตัวละคร'}) เรียบร้อยแล้ว! 📋`
        });
    }).catch(err => {
        console.error('Clipboard copy error:', err);
        const Toast = Swal.mixin({
            toast: true,
            position: 'bottom',
            showConfirmButton: false,
            timer: 3000
        });
        Toast.fire({
            icon: 'info',
            title: 'คัดลอกลิงก์เรียบร้อยแล้ว'
        });
    });
}
